import{_ as t,o,c as a,a2 as i}from"./chunks/framework.lxr64Vqo.js";const u=JSON.parse('{"title":"NoxMedia Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1795117921000}'),n={name:"guide/getting-started.md"};function r(s,e,l,d,c,g){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="noxmedia-documentation" tabindex="-1">NoxMedia Documentation <a class="header-anchor" href="#noxmedia-documentation" aria-label="Permalink to &quot;NoxMedia Documentation&quot;">​</a></h1><section class="doc-section" id="introduction"><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>NoxMedia is a self-hosted personal streaming server that converts your Telegram channels and cloud media into a high-performance local media bridge compatible with Infuse, Vesper, and Nuvio.</p><p>Traditional media servers require massive storage drives and time-consuming downloads. NoxMedia operates on an on-demand cloud streaming architecture:</p><ul><li><strong>Zero Storage Waste</strong>: Streams directly from Telegram cloud storage without saving large video files to disk.</li><li><strong>Hardware DirectPlay</strong>: Native 4K HDR10, Dolby Vision, and multi-track audio decoding performed directly on client hardware.</li><li><strong>Zero Transcoding Overhead</strong>: Lightweight byte-range HTTP pipeline runs effortlessly on modern smartphones, TV boxes, or servers.</li></ul></section><section class="doc-section" id="architecture"><h2 id="architecture-roots" tabindex="-1">Architecture &amp; Roots <a class="header-anchor" href="#architecture-roots" aria-label="Permalink to &quot;Architecture &amp; Roots&quot;">​</a></h2><p>NoxMedia interfaces directly with Telegram&#39;s content delivery network through a high-speed embedded MTProto pipeline:</p><ul><li><strong>Chaquopy Python Core</strong>: Embedded Python 3.11 runtime executing optimized asynchronous MTProto protocol operations.</li><li><strong>Real-Time Seeking</strong>: Supports HTTP 206 Partial Content byte ranges, allowing instant random seeking across multi-gigabyte media files.</li><li><strong>Roots</strong>: Inspired by the foundational concepts of Telegram-Stremio, re-engineered from the ground up for native Android background hosting, automated backup synchronization, and zero-configuration local networking.</li></ul></section><section class="doc-section" id="installation"><h2 id="installation-login" tabindex="-1">Installation &amp; Login <a class="header-anchor" href="#installation-login" aria-label="Permalink to &quot;Installation &amp; Login&quot;">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ol><li>An Android device running Android 7.0 or higher.</li><li>An active Telegram account.</li><li>Your Telegram API credentials (<code>api_id</code> and <code>api_hash</code>).</li></ol><h3 id="step-1-obtain-telegram-api-credentials" tabindex="-1">Step 1: Obtain Telegram API Credentials <a class="header-anchor" href="#step-1-obtain-telegram-api-credentials" aria-label="Permalink to &quot;Step 1: Obtain Telegram API Credentials&quot;">​</a></h3><ol><li>Navigate to <a href="https://my.telegram.org" target="_blank" rel="noreferrer">my.telegram.org</a> in your browser.</li><li>Log in using your phone number with the international country code.</li><li>Select <strong>API development tools</strong>.</li><li>Enter an app title (e.g., <code>NoxMedia</code>) and short name.</li><li>Copy your <strong><code>api_id</code></strong> and <strong><code>api_hash</code></strong>.</li></ol><h3 id="step-2-install-and-authenticate" tabindex="-1">Step 2: Install and Authenticate <a class="header-anchor" href="#step-2-install-and-authenticate" aria-label="Permalink to &quot;Step 2: Install and Authenticate&quot;">​</a></h3><ol><li>Download the latest release from the <a href="https://github.com/TheAceOfficials/NoxMedia/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a> page.</li><li>Open NoxMedia and enter your <code>api_id</code>, <code>api_hash</code>, and phone number.</li><li>Enter the login confirmation code sent to your official Telegram app.</li><li>If Two-Step Verification (2FA) is active, enter your cloud password.</li></ol><h3 id="step-3-start-server" tabindex="-1">Step 3: Start Server <a class="header-anchor" href="#step-3-start-server" aria-label="Permalink to &quot;Step 3: Start Server&quot;">​</a></h3><ol><li>From the home screen, switch the <strong>Server Toggle</strong> to ON.</li><li>Grant requested background battery exemptions so Android does not suspend server operations.</li><li>Note your displayed local address (e.g., <code>http://192.168.1.15:8096</code>).</li></ol></section><section class="doc-section" id="channels-setup"><h2 id="channels-indexing" tabindex="-1">Channels &amp; Indexing <a class="header-anchor" href="#channels-indexing" aria-label="Permalink to &quot;Channels &amp; Indexing&quot;">​</a></h2><p>NoxMedia turns both private and public channels into a structured, searchable catalog.</p><h3 id="supported-channel-identifiers" tabindex="-1">Supported Channel Identifiers <a class="header-anchor" href="#supported-channel-identifiers" aria-label="Permalink to &quot;Supported Channel Identifiers&quot;">​</a></h3><ul><li><strong>Public Channels</strong>: Username format <code>@channelname</code> or URL <code>https://t.me/channelname</code>.</li><li><strong>Private Channels</strong>: Invite link <code>https://t.me/+inviteHash</code> (your authenticated account must be a member).</li><li><strong>Channel IDs</strong>: Numeric identifier (e.g., <code>-1001234567890</code>).</li></ul><h3 id="smart-file-parsing" tabindex="-1">Smart File Parsing <a class="header-anchor" href="#smart-file-parsing" aria-label="Permalink to &quot;Smart File Parsing&quot;">​</a></h3><p>During channel sync, NoxMedia&#39;s engine parses raw file names:</p><ul><li><strong>Title &amp; Year</strong>: Strips release group prefixes while preserving title and release year.</li><li><strong>Season &amp; Episode</strong>: Normalizes standard naming formats (<code>S01E05</code>, <code>1x05</code>, <code>Part 1</code>).</li><li><strong>Quality &amp; Dynamic Range</strong>: Detects <code>2160p (4K)</code>, <code>1080p</code>, <code>HDR10</code>, <code>Dolby Vision</code>, <code>HEVC</code>, and <code>AV1</code>.</li><li><strong>Audio &amp; Subtitles</strong>: Recognizes embedded multi-language tracks (<code>Hindi</code>, <code>English</code>, <code>5.1 AAC</code>, <code>Atmos</code>).</li></ul><h3 id="metadata-providers" tabindex="-1">Metadata Providers <a class="header-anchor" href="#metadata-providers" aria-label="Permalink to &quot;Metadata Providers&quot;">​</a></h3><ul><li><strong>Movies</strong>: Primary matching against TheMovieDatabase (TMDB).</li><li><strong>TV Series</strong>: Comprehensive episode listings via TheTVDB &amp; TMDB.</li><li><strong>Anime</strong>: Romaji title resolution and seasonal mapping via Kitsu.io and AniList.</li></ul></section><section class="doc-section" id="ai-catalogs"><h2 id="ai-custom-shelves" tabindex="-1">AI &amp; Custom Shelves <a class="header-anchor" href="#ai-custom-shelves" aria-label="Permalink to &quot;AI &amp; Custom Shelves&quot;">​</a></h2><p>Instead of rigid static genres, NoxMedia allows you to construct dynamic collections using artificial intelligence or explicit rules.</p><h3 id="ai-assistant-curation" tabindex="-1">AI Assistant Curation <a class="header-anchor" href="#ai-assistant-curation" aria-label="Permalink to &quot;AI Assistant Curation&quot;">​</a></h3><ol><li>Configure your free <strong>Google Gemini API Key</strong> or <strong>OpenRouter API Key</strong> in app settings.</li><li>Navigate to <strong>Catalogs</strong> -&gt; <strong>Create New Shelf</strong> -&gt; <strong>AI Assistant</strong>.</li><li>Provide a natural language description: <blockquote><p><em>&quot;Find all psychological thrillers, neo-noir, and investigative murder mysteries with dark atmospheres and high suspense.&quot;</em></p></blockquote></li><li>NoxMedia analyzes your library&#39;s plot summaries and thematic tags to assemble the shelf.</li></ol><h3 id="rule-based-criteria" tabindex="-1">Rule-Based Criteria <a class="header-anchor" href="#rule-based-criteria" aria-label="Permalink to &quot;Rule-Based Criteria&quot;">​</a></h3><ul><li><strong>Resolution</strong>: Restrict to <code>4K UHD</code> or <code>Dolby Vision</code> only.</li><li><strong>Ratings</strong>: Filter by TMDB score (e.g., <code>Score &gt;= 7.5</code>).</li><li><strong>Genres &amp; Keywords</strong>: Target specific directors, production houses, or tags.</li></ul></section><section class="doc-section" id="cloud-sync"><h2 id="true-cloud-sync-standby" tabindex="-1">True Cloud Sync &amp; Standby <a class="header-anchor" href="#true-cloud-sync-standby" aria-label="Permalink to &quot;True Cloud Sync &amp; Standby&quot;">​</a></h2><p>NoxMedia unifies playback state across your living room and mobile screens.</p><ul><li><strong>Playback Continuity</strong>: Pause a stream on Apple TV via Infuse or Vesper, and resume at the exact second on your phone or PC via Nuvio.</li><li><strong>Watched History</strong>: Scrobbling updates reflect universally across all connected clients.</li><li><strong>24/7 Android Standby</strong>: <ul><li>Run as an Android Foreground Service with continuous wake lock protection.</li><li>Set device battery management to <strong>Unrestricted</strong> / <strong>Don&#39;t Optimize</strong>.</li><li>Ensure Wi-Fi sleep policy is set to <strong>Always on during sleep</strong>.</li></ul></li></ul></section><section class="doc-section" id="infuse-vesper"><h2 id="infuse-vesper-setup-apple-ecosystem" tabindex="-1">Infuse &amp; Vesper Setup (Apple Ecosystem) <a class="header-anchor" href="#infuse-vesper-setup-apple-ecosystem" aria-label="Permalink to &quot;Infuse &amp; Vesper Setup (Apple Ecosystem)&quot;">​</a></h2><p>NoxMedia emulates a Jellyfin server bridge, providing deep native integration with both <a href="https://firecore.com/infuse" target="_blank" rel="noreferrer">Firecore Infuse</a> and <a href="https://watchvesper.app" target="_blank" rel="noreferrer">Vesper</a>.</p><h3 id="connection-parameters" tabindex="-1">Connection Parameters <a class="header-anchor" href="#connection-parameters" aria-label="Permalink to &quot;Connection Parameters&quot;">​</a></h3><ul><li><strong>Protocol</strong>: <code>Jellyfin</code></li><li><strong>Host</strong>: Your host IP (e.g., <code>192.168.1.15</code>)</li><li><strong>Port</strong>: <code>8096</code></li><li><strong>Username</strong>: <code>NoxMedia</code></li><li><strong>Password</strong>: <em>(leave blank)</em></li></ul><h3 id="infuse-direct-mode-recommendation" tabindex="-1">Infuse Direct Mode Recommendation <a class="header-anchor" href="#infuse-direct-mode-recommendation" aria-label="Permalink to &quot;Infuse Direct Mode Recommendation&quot;">​</a></h3><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Use Direct Mode in Infuse.</strong> Browse media via the <strong>Files</strong> tab. Avoid enabling full background library crawling under Infuse Settings -&gt; Library. Direct Mode queries metadata on-demand with zero-latency response times.</p></div><h3 id="pinned-home-screen-favorites" tabindex="-1">Pinned Home Screen Favorites <a class="header-anchor" href="#pinned-home-screen-favorites" aria-label="Permalink to &quot;Pinned Home Screen Favorites&quot;">​</a></h3><ol><li>Open the <strong>Files</strong> tab in Infuse and select your NoxMedia server.</li><li>Locate any custom shelf (e.g., <em>Murder Mystery Dark</em>).</li><li>Long-press or click the <strong>Star</strong> icon to favorite.</li><li>The shelf will appear as a dedicated horizontal row on your Apple TV or iOS Home Screen.</li></ol></section><section class="doc-section" id="nuvio"><h2 id="nuvio-streaming" tabindex="-1">Nuvio Streaming <a class="header-anchor" href="#nuvio-streaming" aria-label="Permalink to &quot;Nuvio Streaming&quot;">​</a></h2><p>NoxMedia exposes an Addon v3 manifest for <a href="https://github.com/nuvio-app" target="_blank" rel="noreferrer">Nuvio</a>.</p><h3 id="manifest-url" tabindex="-1">Manifest URL <a class="header-anchor" href="#manifest-url" aria-label="Permalink to &quot;Manifest URL&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://&lt;YOUR_HOST_IP&gt;:8096/manifest.json</span></span></code></pre></div><h3 id="setup-steps" tabindex="-1">Setup Steps <a class="header-anchor" href="#setup-steps" aria-label="Permalink to &quot;Setup Steps&quot;">​</a></h3><ol><li>Open Nuvio on Android, Windows, macOS, or Web.</li><li>Navigate to <strong>Settings</strong> -&gt; <strong>Providers &amp; Addons</strong> -&gt; <strong>Add Custom Provider</strong>.</li><li>Paste your manifest URL and click <strong>Connect</strong>.</li><li>Your Telegram library and custom shelves will populate the home feed.</li></ol><h3 id="notice-on-stremio-support" tabindex="-1">Notice on Stremio Support <a class="header-anchor" href="#notice-on-stremio-support" aria-label="Permalink to &quot;Notice on Stremio Support&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Direct playback in Stremio is temporarily on hold while we resolve an issue related to Stremio&#39;s handling of localhost HTTP streaming URLs on Android. In the interim, <strong>Nuvio</strong> is the officially recommended client.</p></div></section><section class="doc-section" id="android-tv-kodi"><h2 id="android-tv-kodi-guide" tabindex="-1">Android TV &amp; Kodi Guide <a class="header-anchor" href="#android-tv-kodi-guide" aria-label="Permalink to &quot;Android TV &amp; Kodi Guide&quot;">​</a></h2><h3 id="method-1-nuvio-for-android-tv" tabindex="-1">Method 1: Nuvio for Android TV <a class="header-anchor" href="#method-1-nuvio-for-android-tv" aria-label="Permalink to &quot;Method 1: Nuvio for Android TV&quot;">​</a></h3><p>Install the Nuvio Android TV APK, add the manifest URL, and navigate catalogs using standard remote controls.</p><h3 id="method-2-kodi-jellyfin-addon" tabindex="-1">Method 2: Kodi Jellyfin Addon <a class="header-anchor" href="#method-2-kodi-jellyfin-addon" aria-label="Permalink to &quot;Method 2: Kodi Jellyfin Addon&quot;">​</a></h3><ol><li>Install the official <strong>Jellyfin for Kodi</strong> addon.</li><li>Point server address to <code>http://&lt;YOUR_IP&gt;:8096</code>.</li><li>Select <strong>Add-on (HTTP Stream)</strong> mode.</li><li>Browse structured libraries and custom shelves directly from Kodi.</li></ol></section><section class="doc-section" id="platforms"><h2 id="platform-compatibility" tabindex="-1">Platform Compatibility <a class="header-anchor" href="#platform-compatibility" aria-label="Permalink to &quot;Platform Compatibility&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Client / Platform</th><th style="text-align:left;">Supported Operating Systems</th><th style="text-align:left;">Connection Protocol</th><th style="text-align:left;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Infuse</strong></td><td style="text-align:left;">Apple TV, iOS, iPadOS, macOS, visionOS</td><td style="text-align:left;">Jellyfin Bridge (Direct Mode)</td><td style="text-align:left;">Available Now</td></tr><tr><td style="text-align:left;"><strong>Vesper</strong></td><td style="text-align:left;">macOS, iOS, iPadOS, tvOS</td><td style="text-align:left;">Jellyfin Bridge</td><td style="text-align:left;">Available Now</td></tr><tr><td style="text-align:left;"><strong>Nuvio</strong></td><td style="text-align:left;">Android, Windows, macOS, Web</td><td style="text-align:left;">Stremio v3 Addon Protocol</td><td style="text-align:left;">Available Now</td></tr><tr><td style="text-align:left;"><strong>Kodi / EmbyCon</strong></td><td style="text-align:left;">Android TV, Shield TV, Fire TV, PC</td><td style="text-align:left;">Jellyfin / Emby Addon</td><td style="text-align:left;">Available Now</td></tr><tr><td style="text-align:left;"><strong>Native Android TV App</strong></td><td style="text-align:left;">Android TV, Google TV</td><td style="text-align:left;">Native D-Pad Player</td><td style="text-align:left;">Coming Soon</td></tr><tr><td style="text-align:left;"><strong>Windows Desktop Native</strong></td><td style="text-align:left;">Windows 10, 11 (x64 / ARM64)</td><td style="text-align:left;">Standalone Client</td><td style="text-align:left;">Coming Soon</td></tr><tr><td style="text-align:left;"><strong>Linux Client / Server</strong></td><td style="text-align:left;">Ubuntu, Debian, Arch</td><td style="text-align:left;">Standalone &amp; Headless</td><td style="text-align:left;">Coming Soon</td></tr></tbody></table></section>',11)])])}const p=t(n,[["render",r]]);export{u as __pageData,p as default};
